/* Myrmex Hub: theme toggle + cloud sync (Supabase). Shared by all pages. */
(function(){
'use strict';
var root=document.documentElement,TK='myrmex_theme';
var LIGHT_LOGO="data:image/png;base64,";
var LQH='--text:#1B1F1D;--text-secondary:#4B5A50;--text-muted:#6B7A70;--border:#D7E2DA;--border-strong:#BFCDC3;--surface:#F4F7F5;--panel:#fff;--card:#fff;--field:#EEF3EF;--brand-light:rgba(56,142,60,.14);--shadow:0 2px 10px rgba(0,0,0,.08);--sec:#4B5A50;--mut:#6B7A70;--bd:#D7E2DA;--bds:#BFCDC3;--surf:#F4F7F5;';
var LR='--ink:#1b1f1d;--mu:#5b6b60;--bg:#f4f7f5;--cd:#fff;';
var DR=':root[data-theme=dark]{--ink:#eef1ef;--mu:#a9b6ae;--bd:#2c3b31;--bg:#121712;--cd:#182019}';
var st=document.createElement('style');
st.textContent=':root[data-theme=light]{'+LQH+LR+'}@media(prefers-color-scheme:light){:root:not([data-theme]){'+LQH+'}}'+DR+'@media print{#hubDock,#hubBan,#hubModal{display:none!important}}body{padding-bottom:64px}';
document.head.appendChild(st);
function eff(){var t=localStorage.getItem(TK);return t==='light'||t==='dark'?t:(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark')}
function applyTheme(){var t=localStorage.getItem(TK);
 if(t==='light'||t==='dark')root.setAttribute('data-theme',t);else root.removeAttribute('data-theme');
 document.querySelectorAll('img.page-logo,img.logo').forEach(function(i){if(!i.dataset.o)i.dataset.o=i.src;i.src=eff()==='light'?LIGHT_LOGO:i.dataset.o});
 var b=document.getElementById('hubTheme');if(b)b.textContent='◐ '+(t==='light'?'Light':t==='dark'?'Dark':'Auto')}
applyTheme();

/* ---------- sync ---------- */
var SB_URL='https://wwlafidmnhlvvvmsqspt.supabase.co',SB_KEY='sb_publishable_53b4jHTkRnkHBv2nxyCIQw_pflj9fep';
var KINDS={myrmex_standalone_quotes:'quote',myrmex_invoices:'invoice',myrmexReports_v2:'report'};
var KEYOF={quote:'myrmex_standalone_quotes',invoice:'myrmex_invoices',report:'myrmexReports_v2'};
var _set=Storage.prototype.setItem,applying=false,sb=null,user=null,busy=false,started=null,pt=null,ft=null,chan=null;
function rd(k,d){try{var v=localStorage.getItem(k);return v?JSON.parse(v):d}catch(e){return d}}
function wr(k,v){_set.call(localStorage,k,JSON.stringify(v))}
function canon(o){return JSON.stringify(o,function(k,v){if(v&&typeof v==='object'&&!Array.isArray(v)){var s={};Object.keys(v).sort().forEach(function(x){s[x]=v[x]});return s}return v})}
var meta=rd('myrmex_sync_meta',{}),dirty=rd('myrmex_sync_dirty',{});
function saveMeta(){wr('myrmex_sync_meta',meta)}function saveDirty(){wr('myrmex_sync_dirty',dirty)}
function map(raw){var m={};try{(JSON.parse(raw)||[]).forEach(function(d){if(d&&d.id!=null)m[String(d.id)]=canon(d)})}catch(e){}return m}
Storage.prototype.setItem=function(k,v){
 if(this===localStorage&&KINDS[k]&&!applying){try{var o=map(this.getItem(k)),n=map(v),kind=KINDS[k],id;
  for(id in n)if(o[id]!==n[id])dirty[kind+':'+id]='u';
  for(id in o)if(!(id in n))dirty[kind+':'+id]='d';
  saveDirty();schedule()}catch(e){}}
 return _set.apply(this,arguments)};
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function chip(t,title){var c=document.getElementById('hubSync');if(c){c.textContent='☁ '+t;c.title=title||''}}
function schedule(){clearTimeout(ft);ft=setTimeout(function(){flush()},900)}
async function flush(){
 if(!sb||!user||busy)return;
 if(!navigator.onLine){chip('Offline');return}
 busy=true;
 try{var keys=Object.keys(dirty);
  if(!keys.length){chip('Synced');return}
  chip('Syncing…');
  var rows=[];
  keys.forEach(function(key){var i=key.indexOf(':'),kind=key.slice(0,i),id=key.slice(i+1);
   if(dirty[key]==='d')rows.push({user_id:user.id,kind:kind,doc_id:id,data:{},deleted:true});
   else{var doc=rd(KEYOF[kind],[]).find(function(x){return String(x.id)===id});
    if(doc)rows.push({user_id:user.id,kind:kind,doc_id:id,data:doc,deleted:false});else delete dirty[key]}});
  var chunk=[],size=0;
  var send=async function(){if(!chunk.length)return;
   var r=await sb.from('hub_docs').upsert(chunk,{onConflict:'user_id,kind,doc_id'});if(r.error)throw r.error;
   chunk.forEach(function(x){delete dirty[x.kind+':'+x.doc_id]});saveDirty();chunk=[];size=0};
  for(var j=0;j<rows.length;j++){var sz=JSON.stringify(rows[j]).length;if(chunk.length&&size+sz>700000)await send();chunk.push(rows[j]);size+=sz}
  await send();saveDirty();chip('Synced');
 }catch(e){chip('Sync error','Tap for details: '+(e.message||e))}
 finally{busy=false}}
function apply(rows){var by={},n=0;
 rows.forEach(function(r){(by[r.kind]=by[r.kind]||[]).push(r)});
 applying=true;
 try{for(var kind in by){var key=KEYOF[kind];if(!key)continue;var arr=rd(key,[]),ch=false;
  by[kind].forEach(function(r){if(dirty[kind+':'+r.doc_id])return;
   var i=arr.findIndex(function(x){return String(x.id)===r.doc_id});
   if(r.deleted){if(i>=0){arr.splice(i,1);ch=true}}
   else if(i<0){arr.unshift(r.data);ch=true}
   else if(canon(arr[i])!==canon(r.data)){arr[i]=r.data;ch=true}});
  if(ch){wr(key,arr);n++}}}
 finally{applying=false}
 return n}
async function pull(){var since=meta.lastPull||'1970-01-01T00:00:00Z',changed=0;
 for(;;){var r=await sb.from('hub_docs').select('kind,doc_id,data,deleted,updated_at').gt('updated_at',since).order('updated_at',{ascending:true}).limit(100);
  if(r.error)throw r.error;var rows=r.data||[];if(!rows.length)break;
  changed+=apply(rows);since=rows[rows.length-1].updated_at;meta.lastPull=since;saveMeta();if(rows.length<100)break}
 return changed}
function banner(){if(document.getElementById('hubBan'))return;var d=document.createElement('div');d.id='hubBan';
 d.style.cssText='position:fixed;top:0;left:0;right:0;z-index:60;background:#388E3C;color:#fff;font:600 13px -apple-system,Segoe UI,sans-serif;padding:10px 14px;text-align:center';
 d.innerHTML='Updated from another device. <a href="" style="color:#fff;text-decoration:underline">Refresh</a>';document.body.appendChild(d)}
async function refresh(){if(!sb||!user||busy)return;
 try{await flush();var c=await pull();if(c)banner();chip('Synced')}catch(e){chip('Sync error','Tap for details: '+(e.message||e))}}
function listen(){if(chan)return;try{chan=sb.channel('hub-docs').on('postgres_changes',{event:'*',schema:'public',table:'hub_docs'},function(){clearTimeout(pt);pt=setTimeout(refresh,600)}).subscribe()}catch(e){}}
async function start(){if(started===user.id)return;started=user.id;
 if(meta.uid!==user.id){meta={uid:user.id,init:0};saveMeta()}
 if(!meta.init){Object.keys(KINDS).forEach(function(k){rd(k,[]).forEach(function(d){if(d&&d.id!=null)dirty[KINDS[k]+':'+d.id]='u'})});saveDirty();meta.init=1;saveMeta()}
 try{chip('Syncing…');await flush();var c=await pull();
  if(c){if(performance.now()<12000){location.reload();return}banner()}
  chip('Synced');listen()}catch(e){chip('Sync error','Tap for details: '+(e.message||e))}}
addEventListener('online',refresh);addEventListener('focus',refresh);

/* ---------- UI ---------- */
var IN='width:100%;padding:9px 10px;margin-bottom:8px;border-radius:7px;border:1px solid #323A2E;background:#1C231C;color:#EEF1EC;font-size:14px;box-sizing:border-box';
var BT='padding:9px 16px;border-radius:8px;border:0;background:#388E3C;color:#fff;font-weight:600;cursor:pointer';
var BT2='padding:9px 16px;border-radius:8px;border:1px solid #323A2E;background:transparent;color:#EEF1EC;font-weight:600;cursor:pointer';
function closeM(){var m=document.getElementById('hubModal');if(m)m.remove()}
function modal(html){closeM();var m=document.createElement('div');m.id='hubModal';
 m.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;z-index:70;background:rgba(0,0,0,.55);display:flex;align-items:center;justify-content:center;padding:16px;font-family:-apple-system,Segoe UI,sans-serif';
 m.innerHTML='<div style="background:#101510;color:#EEF1EC;border:1px solid #323A2E;border-radius:12px;padding:20px;width:100%;max-width:340px">'+html+'</div>';
 document.body.appendChild(m);return m}
function login(){var m=modal('<b style="font-size:16px">Sign in to sync</b><p style="font-size:12.5px;color:#A9B2A6;margin:6px 0 12px">Sign in with your Myrmex hub account to keep your phone and desktop in step.</p><input id="hEm" type="email" placeholder="Email" autocomplete="username" style="'+IN+'"><input id="hPw" type="password" placeholder="Password" autocomplete="current-password" style="'+IN+'"><div id="hEr" style="color:#FF6568;font-size:12px;min-height:16px;margin-bottom:6px"></div><button id="hGo" style="'+BT+'">Sign in</button> <button id="hNo" style="'+BT2+'">Not now</button>');
 m.querySelector('#hNo').onclick=closeM;
 m.querySelector('#hGo').onclick=async function(){var r=await sb.auth.signInWithPassword({email:m.querySelector('#hEm').value.trim(),password:m.querySelector('#hPw').value});
  if(r.error){m.querySelector('#hEr').textContent=r.error.message;return}closeM()}}
function panel(){var m=modal('<b style="font-size:16px">Cloud sync</b><p style="font-size:12.5px;color:#A9B2A6;margin:6px 0 12px">Signed in as '+esc(user.email||'')+'</p><button id="hSy" style="'+BT+'">Sync now</button> <button id="hOut" style="'+BT2+'">Sign out</button> <button id="hX" style="'+BT2+'">Close</button>');
 m.querySelector('#hX').onclick=closeM;
 m.querySelector('#hSy').onclick=function(){closeM();refresh()};
 m.querySelector('#hOut').onclick=async function(){await sb.auth.signOut();try{sb.removeAllChannels()}catch(e){}chan=null;user=null;started=null;chip('Sign in to sync');closeM()}}
function init(){
 var CH='padding:7px 12px;border-radius:20px;border:1px solid #6b7a70;background:rgba(20,28,20,.92);color:#EEF1EC;font:600 12px -apple-system,Segoe UI,sans-serif;cursor:pointer';
 var d=document.createElement('div');d.id='hubDock';d.style.cssText='position:fixed;right:12px;bottom:12px;display:flex;gap:8px;z-index:50';
 d.innerHTML='<button id="hubTheme" style="'+CH+'"></button><button id="hubSync" style="'+CH+'">☁ …</button>';document.body.appendChild(d);
 document.getElementById('hubTheme').onclick=function(){var t=localStorage.getItem(TK);var n=t==='light'?'dark':t==='dark'?'auto':'light';
  if(n==='auto')localStorage.removeItem(TK);else localStorage.setItem(TK,n);applyTheme()};
 applyTheme();
 document.getElementById('hubSync').onclick=function(){if(!sb)alert('Sync needs an internet connection. It will start automatically when you are online.');else if(user)panel();else login()};
 if(!window.supabase){chip('Offline mode');return}
 sb=window.supabase.createClient(SB_URL,SB_KEY);
 sb.auth.onAuthStateChange(function(ev,s){user=s&&s.user||null;if(user){closeM();setTimeout(start,0)}else chip('Sign in to sync')});
 sb.auth.getSession().then(function(r){var s=r.data&&r.data.session;
  if(s){user=s.user;start()}else{chip('Sign in to sync');if(!sessionStorage.getItem('hubAsked')){sessionStorage.setItem('hubAsked','1');login()}}})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
